<?php
declare(strict_types=1);

$rankLimit=max(1,(int)($round['callback_count']??10));
$locked=(string)$session['status']==='submitted';

if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if($locked)throw new RuntimeException('Scores are already submitted and locked.');
  $action=(string)($_POST['action']??'save_score');
  if($action==='save_score'){
   $pairId=(int)($_POST['pair_id']??0);$raw=trim((string)($_POST['value']??''));
   $pair=$pdo->prepare("SELECT id FROM bdc_test_scoring_final_pairs WHERE id=:pair AND round_id=:round AND pairing_status='confirmed'");$pair->execute(['pair'=>$pairId,'round'=>$roundId]);if(!(int)$pair->fetchColumn())throw new RuntimeException('Final pair not found.');
   if($raw==='')$pdo->prepare('DELETE FROM bdc_test_scoring_final_marks WHERE round_id=:round AND pair_id=:pair AND judge_id=:judge')->execute(['round'=>$roundId,'pair'=>$pairId,'judge'=>$judgeId]);
   else{
    if(!ctype_digit($raw)||(int)$raw<1||(int)$raw>$rankLimit)throw new RuntimeException('Ranks must be between 1 and '.$rankLimit.'.');
    $duplicate=$pdo->prepare('SELECT pair_id FROM bdc_test_scoring_final_marks WHERE round_id=:round AND judge_id=:judge AND rank_value=:rank AND pair_id<>:pair LIMIT 1');$duplicate->execute(['round'=>$roundId,'judge'=>$judgeId,'rank'=>(int)$raw,'pair'=>$pairId]);if($duplicate->fetchColumn())throw new RuntimeException('Rank '.$raw.' is already assigned to another couple.');
    $pdo->prepare('INSERT INTO bdc_test_scoring_final_marks(round_id,pair_id,judge_id,rank_value,updated_by) VALUES(:round,:pair,:judge,:rank,NULL) ON DUPLICATE KEY UPDATE rank_value=VALUES(rank_value),updated_by=NULL,updated_at=NOW()')->execute(['round'=>$roundId,'pair'=>$pairId,'judge'=>$judgeId,'rank'=>(int)$raw]);
   }
   TestAutomaticJudgeService::markSaved($pdo,$sessionId);header('Content-Type:application/json');echo json_encode(['ok'=>true,'saved_at'=>date('H:i:s')]);exit;
  }
  if($action==='submit'){
   $q=$pdo->prepare('SELECT rank_value FROM bdc_test_scoring_final_marks WHERE round_id=:round AND judge_id=:judge ORDER BY rank_value');$q->execute(['round'=>$roundId,'judge'=>$judgeId]);$values=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));if(count($values)!==$rankLimit||$values!==range(1,$rankLimit))throw new RuntimeException('Assign each Top '.$rankLimit.' rank exactly once before submitting.');TestAutomaticJudgeService::submit($pdo,$sessionId);$locked=true;$notice='Scores submitted and locked.';
  }
 }catch(Throwable $e){if(($_POST['action']??'')==='save_score'){http_response_code(422);header('Content-Type:application/json');echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);exit;}$error=$e->getMessage();}
}

$q=$pdo->prepare("SELECT fp.id pair_id,fp.pair_number,le.display_name leader_name,le.bib_number leader_bib,fe.display_name follower_name,fe.bib_number follower_bib,fm.rank_value FROM bdc_test_scoring_final_pairs fp JOIN bdc_test_scoring_entries le ON le.id=fp.leader_entry_id JOIN bdc_test_scoring_entries fe ON fe.id=fp.follower_entry_id LEFT JOIN bdc_test_scoring_final_marks fm ON fm.round_id=fp.round_id AND fm.pair_id=fp.id AND fm.judge_id=:judge WHERE fp.round_id=:round AND fp.pairing_status='confirmed' ORDER BY fp.pair_number");$q->execute(['judge'=>$judgeId,'round'=>$roundId]);$pairs=$q->fetchAll();$rankLimit=min(count($pairs),$rankLimit);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Final Judge Scoring</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#172033;font-family:Arial,sans-serif}.top{background:#172033;color:#fff;padding:18px;border-bottom:5px solid #ffc107}.wrap{max-width:760px;margin:auto;padding:14px}.test{color:#ffc107;font-weight:900}.card{border:1px solid #dfe3e8;border-left:7px solid #dc3545;border-radius:14px;background:linear-gradient(110deg,#fff7f8,#fff 42%);padding:14px;margin-bottom:10px}.card.placed{border-left-color:#16794c;background:linear-gradient(110deg,#edf9f3,#fff 45%)}.head{display:flex;justify-content:space-between;gap:10px}.bib{font-size:25px;font-weight:900}.name{color:#667085;font-weight:700}.badge{height:max-content;border-radius:999px;padding:7px 10px;background:#fff0f2;color:#a7192c;font-size:12px;font-weight:900}.placed .badge{background:#16794c;color:#fff}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin-top:12px}.rank,.clear{min-height:44px;border:2px solid #cbd5e1;border-radius:10px;background:#fff;font-size:17px;font-weight:900}.rank.selected{background:#16794c;color:#fff}.clear{grid-column:span 5;border-color:#dc3545;color:#b42318}.toolbar{position:sticky;top:0;z-index:3;background:#f4f6f9;padding:9px 0;font-weight:900}.missing{color:#b42318}.submit{width:100%;padding:14px;border:0;border-radius:10px;background:#146c43;color:#fff;font-weight:900}.submit:disabled{background:#98a2b3}.alert{padding:12px;border-radius:9px;background:#ffe6e6;color:#8a1010;margin-bottom:10px}@media(max-width:520px){.wrap{padding:10px}.bib{font-size:22px}}</style></head><body><header class="top"><div class="wrap"><div class="test">BDC AUTOMATIC SCORING · TEST ONLY</div><h2><?=e($session['event_name'])?></h2><div><?=e($session['judge_name'])?> · FINAL</div></div></header><main class="wrap"><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($locked):?><div class="alert" style="background:#e4f6ea;color:#176b36">Scores submitted and locked.</div><?php else:?><div class="toolbar"><span id="progress"></span><br><span id="missing" class="missing"></span></div><?php foreach($pairs as $pair):?><div class="card" data-card><div class="head"><div><small>PAIR #<?=(int)$pair['pair_number']?></small><div class="bib">BIB <?=(int)$pair['leader_bib']?> + BIB <?=(int)$pair['follower_bib']?></div><div class="name"><?=e($pair['leader_name'])?> &amp; <?=e($pair['follower_name'])?></div></div><div class="badge">NO RANK</div></div><input type="hidden" class="value" data-pair="<?=(int)$pair['pair_id']?>" data-label="Pair <?=(int)$pair['pair_number']?>" value="<?=e((string)($pair['rank_value']??''))?>"><div class="grid"><?php for($r=1;$r<=$rankLimit;$r++):?><button type="button" class="rank" data-rank="<?=$r?>"><?=$r?></button><?php endfor;?><button type="button" class="clear">NO RANK</button></div></div><?php endforeach;?><form method="post"><input type="hidden" name="token" value="<?=e($token)?>"><button class="submit" id="submit" name="action" value="submit" disabled>COMPLETE TOP <?=$rankLimit?></button></form><?php endif;?></main><?php if(!$locked):?><script>const token=<?=json_encode($token)?>,limit=<?=$rankLimit?>,inputs=[...document.querySelectorAll('.value')];function message(x){alert(x)}function paint(){const used=new Set(inputs.map(x=>x.value).filter(Boolean));document.querySelectorAll('[data-card]').forEach(card=>{const input=card.querySelector('.value'),placed=input.value!=='';card.classList.toggle('placed',placed);card.querySelector('.badge').textContent=placed?'PLACED #'+input.value:'NO RANK';card.querySelectorAll('.rank').forEach(b=>b.classList.toggle('selected',b.dataset.rank===input.value))});const missing=[];for(let r=1;r<=limit;r++)if(!used.has(String(r)))missing.push(r);document.getElementById('progress').textContent='Placed '+used.size+' of '+limit;document.getElementById('missing').textContent=missing.length?'Missing: '+missing.join(', '):'All placements complete';submit.disabled=missing.length>0;submit.textContent=missing.length?'COMPLETE TOP '+limit:'READY TO SUBMIT FINAL'}async function save(input){const body=new URLSearchParams({token,action:'save_score',pair_id:input.dataset.pair,value:input.value});const r=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Save failed')}inputs.forEach(input=>{input.dataset.previous=input.value;const set=async value=>{const other=inputs.find(x=>x!==input&&value&&x.value===value);if(other){if(!confirm('Rank '+value+' is assigned to '+other.dataset.label+'. Move it here?'))return;other.value='';await save(other)}const old=input.value;input.value=value;paint();try{await save(input);input.dataset.previous=value}catch(e){input.value=old;paint();message(e.message)}};input.closest('[data-card]').querySelectorAll('.rank').forEach(b=>b.onclick=()=>set(b.dataset.rank));input.closest('[data-card]').querySelector('.clear').onclick=()=>set('')});paint();</script><?php endif;?></body></html>
